exercises.solution:
const alunos = [
  { nome: 'Júlia', plano: 'anual', ativo: true },
  { nome: 'Rui', plano: 'mensal', ativo: false },
  { nome: 'Nina', plano: 'mensal', ativo: true },
  { nome: 'Otávio', plano: 'anual', ativo: false },
  { nome: 'Sara', plano: 'mensal', ativo: true },
];

const ativos = alunos.filter((aluno) => aluno.ativo);
const anuais = alunos.filter((aluno) => aluno.plano === 'anual');

console.log('Total de alunos:', alunos.length);
console.log('Alunos ativos:', ativos.length);
console.log('Plano anual:', anuais.length);

