exercises.solution:
const linhas = [
  { numero: 101, destino: 'Praia', tarifa: 5 },
  { numero: 150, destino: 'Centro', tarifa: 7 },
  { numero: 205, destino: 'Centro', tarifa: 5 },
  { numero: 310, destino: 'Estádio', tarifa: 4 },
  { numero: 422, destino: 'Centro', tarifa: 4 },
];

const paraOCentro = linhas.filter((linha) => linha.destino === 'Centro');
const baratas = paraOCentro.filter((linha) => linha.tarifa < 6);

console.log('Ônibus no terminal:', linhas.length);
console.log('Vão ao Centro:', paraOCentro.length);
console.log('Tarifa menor que 6:', baratas.length);
console.log('Primeira opção:', baratas[0].numero);

